/**
 * dataset_display.js — Dataset Display section for HCopilot.
 *
 * Serves: the #datasets-grid container inside the "Datasets" section of index.html.
 * Cards in the grid are generated by app.js using createDatasetCard() and
 * createManagedDatasetCard() defined below.
 *
 * Two families of dataset cards are rendered here:
 *
 *   1. MANAGED datasets (Doctors, Nurses, EDbeds):
 *      - Defined in the MANAGED_DATASETS registry (utils.js).
 *      - Data is fetched in one shot from a local API endpoint and paginated
 *        client-side (all rows kept in managedState[id].allData).
 *      - Each card has Add / Edit / Delete action buttons wired to callbacks
 *        supplied by the registry entry.
 *
 *   2. Read-only datasets (Patients, EDstays, …):
 *      - Defined in the DATASETS registry (utils.js).
 *      - Data is fetched page-by-page from the server-side paginated endpoint
 *        GET /api/patient-flow/data/{id}?page=N&page_size=50.
 *      - An "Update" button POSTs to /api/patient-flow/refresh-data/{id} to pull fresh
 *        data from the external API server (port 8100) and then reloads p.1.
 *      - localOnly datasets skip the Update button (they have no remote source).
 *
 * Key module-level state:
 *   state        — pagination state for read-only cards (keyed by dataset id)
 *                  { currentPage, pageSize, totalPages, totalRecords }
 *   managedState — pagination state for managed cards (keyed by dataset id)
 *                  { currentPage, pageSize, allData: [], totalPages }
 */

// ── Module-level state ────────────────────────────────────────────────────────

// Per-dataset pagination state for read-only cards.
// Populated when a card is first viewed and updated on each page navigation.
// Shape: { currentPage: number, pageSize: number, totalPages: number, totalRecords: number }
const state = {};

// Per-dataset state for managed cards.
// allData holds the full fetched array so client-side pagination can slice it
// without making additional network requests.
// Shape: { currentPage: number, pageSize: number, allData: Array|null, totalPages: number }
const managedState = {};

// ── Managed dataset cards (Doctors / Nurses / EDbeds) ──────────────────────

/**
 * @description Generate the full HTML string for a managed dataset card.
 * The card contains a header with title and record-count info, View / Refresh
 * action buttons, a table area (hidden until View is clicked), and pagination controls.
 * IDs are prefixed with "md-" to avoid collisions with read-only card element IDs.
 *
 * @param {Object} dataset          - Entry from the MANAGED_DATASETS registry.
 * @param {string} dataset.id       - Unique identifier used to build element IDs.
 * @param {string} dataset.name     - Human-readable dataset name shown in the card header.
 * @param {string} dataset.icon     - Emoji icon shown before the name.
 * @returns {string} HTML string to be inserted into #datasets-grid.
 */
function createManagedDatasetCard(dataset) {
    return `
        <div class="dataset-card" id="md-card-${dataset.id}">
            <div class="dataset-header">
                <div class="dataset-title">${dataset.icon} ${dataset.name}</div>
                <div class="dataset-info" id="md-info-${dataset.id}">Click "View" to load data</div>
            </div>
            <div class="dataset-actions">
                <button class="btn btn-primary" onclick="viewManagedDataset('${dataset.id}')">📊 View</button>
                <button class="btn btn-success" onclick="updateManagedDataset('${dataset.id}')">🔄 Refresh</button>
            </div>
            <div class="table-container" id="md-table-${dataset.id}">
                <table>
                    <thead id="md-thead-${dataset.id}"></thead>
                    <tbody id="md-tbody-${dataset.id}"></tbody>
                </table>
            </div>
            <div class="pagination" id="md-pagination-${dataset.id}">
                <div class="pagination-controls">
                    <button class="btn btn-primary" onclick="loadManagedPage('${dataset.id}', 1)">⏮ First</button>
                    <button class="btn btn-primary" onclick="loadManagedPage('${dataset.id}', 'prev')">◀ Prev</button>
                    <button class="btn btn-primary" onclick="loadManagedPage('${dataset.id}', 'next')">Next ▶</button>
                    <button class="btn btn-primary" onclick="loadManagedPage('${dataset.id}', 'last')">Last ⏭</button>
                </div>
                <div class="pagination-info" id="md-page-info-${dataset.id}"></div>
            </div>
        </div>`;
}

/**
 * @description Delegate the "Add" button click to the dataset registry's openAdd() callback.
 * The callback is defined per-dataset in MANAGED_DATASETS (utils.js) so that
 * this file does not need to know the specific modal function for each entity.
 *
 * @param {string} datasetId - ID of the managed dataset (e.g. 'Doctors').
 */
function managedAdd(datasetId) {
    const cfg = MANAGED_DATASETS.find(d => d.id === datasetId);
    if (cfg) cfg.openAdd();
}

/**
 * @description Handle the "View" button: reset pagination to page 1 and fetch all data.
 * Creates a fresh state entry so any previous page position is discarded.
 *
 * @param {string} datasetId - ID of the managed dataset.
 */
function viewManagedDataset(datasetId) {
    managedState[datasetId] = { currentPage: 1, pageSize: 50, allData: null, totalPages: 1 };
    loadManagedDisplay(datasetId);
}

/**
 * @description Handle the "Refresh" button: re-fetch data while keeping the current page.
 * If no state exists yet (the user clicked Refresh before View), initialises from page 1.
 *
 * @param {string} datasetId - ID of the managed dataset.
 */
function updateManagedDataset(datasetId) {
    if (!managedState[datasetId]) {
        // Initialise state if the user refreshes before ever viewing the card
        managedState[datasetId] = { currentPage: 1, pageSize: 50, allData: null, totalPages: 1 };
    }
    loadManagedDisplay(datasetId);
}

/**
 * @description Fetch all rows from the managed dataset's API endpoint and store them
 * in managedState[datasetId].allData, then render the current page.
 *
 * Pagination is done entirely client-side: all rows are kept in s.allData and
 * sliced on each page render. This is acceptable for small datasets like Doctors,
 * Nurses, and Beds which typically have at most a few hundred rows, so fetching
 * all of them in one request avoids the complexity of server-side paging.
 *
 * The current page is clamped to totalPages so it stays valid after a refresh
 * that returns fewer records than before (e.g. after a delete).
 *
 * @param {string} datasetId - ID of the managed dataset to load.
 * @returns {Promise<void>}
 */
async function loadManagedDisplay(datasetId) {
    const cfg = MANAGED_DATASETS.find(d => d.id === datasetId);
    if (!cfg) return;

    const s = managedState[datasetId];
    if (!s) return;

    const tableContainer = document.getElementById('md-table-' + datasetId);
    const tbody          = document.getElementById('md-tbody-' + datasetId);
    const infoEl         = document.getElementById('md-info-'  + datasetId);
    if (!tableContainer || !tbody) return;

    // Show a loading spinner while the fetch is in progress
    tbody.innerHTML = '<tr><td colspan="100"><div class="loading"><div class="spinner"></div>Loading data...</div></td></tr>';
    tableContainer.classList.add('visible');

    try {
        const res    = await fetch(cfg.fetchUrl);
        const result = await res.json();
        if (!res.ok) throw new Error(result.detail || 'HTTP ' + res.status);

        // Extract the rows array using the registry-specified key (e.g. 'doctors', 'beds')
        const data = result[cfg.dataKey] || [];
        s.allData    = data;
        s.totalPages = Math.max(1, Math.ceil(data.length / s.pageSize));
        // Clamp current page in case the dataset shrank since last view
        s.currentPage = Math.min(s.currentPage, s.totalPages);

        infoEl.textContent = data.length.toLocaleString() + ' records';
        displayManagedPage(datasetId);
        updateManagedPagination(datasetId);

    } catch (err) {
        tbody.innerHTML = '<tr><td colspan="100" style="color:#dc3545;text-align:center;padding:20px;">Error: ' + err.message + '</td></tr>';
        infoEl.textContent = 'Error';
    }
}

/**
 * @description Slice allData to the current page and render it into the card's table.
 * Column headers and cell values are derived from cfg.columns (label + key pairs)
 * defined in the MANAGED_DATASETS registry, not from the response keys directly,
 * so the display order and labels are controlled by the registry definition.
 *
 * @param {string} datasetId - ID of the managed dataset to render.
 */
function displayManagedPage(datasetId) {
    const cfg = MANAGED_DATASETS.find(d => d.id === datasetId);
    const s   = managedState[datasetId];
    if (!cfg || !s || !s.allData) return;

    const thead = document.getElementById('md-thead-' + datasetId);
    const tbody = document.getElementById('md-tbody-' + datasetId);

    if (s.allData.length === 0) {
        thead.innerHTML = '';
        tbody.innerHTML = '<tr><td style="text-align:center;padding:40px;color:#6c757d;">No data. Click ➕ Add to create records.</td></tr>';
        return;
    }

    // Calculate the slice bounds for the current page
    const start    = (s.currentPage - 1) * s.pageSize;
    const pageData = s.allData.slice(start, start + s.pageSize);

    // Build header row from the registry column labels (not raw API keys)
    thead.innerHTML = '<tr>' + cfg.columns.map(c => '<th>' + c.label + '</th>').join('') + '</tr>';

    // Render each row; use '–' for null/undefined values so cells are never blank
    tbody.innerHTML = pageData.map(row => {
        const cells = cfg.columns.map(c => {
            const v = row[c.key];
            return '<td>' + (v !== null && v !== undefined ? v : '–') + '</td>';
        }).join('');
        return '<tr>' + cells + '</tr>';
    }).join('');
}

/**
 * @description Navigate to a specific page of a managed dataset card.
 * Resolves symbolic page names ('prev', 'next', 'last') to absolute numbers,
 * clamping to the valid range [1, totalPages].
 *
 * @param {string}        datasetId - ID of the managed dataset.
 * @param {number|string} page      - Absolute page number, or 'prev'/'next'/'last'.
 */
function loadManagedPage(datasetId, page) {
    const s = managedState[datasetId];
    if (!s) return;
    if (page === 'prev') s.currentPage = Math.max(1, s.currentPage - 1);
    else if (page === 'next') s.currentPage = Math.min(s.totalPages, s.currentPage + 1);
    else if (page === 'last') s.currentPage = s.totalPages;
    else s.currentPage = page;
    displayManagedPage(datasetId);
    updateManagedPagination(datasetId);
}

/**
 * @description Update the pagination info bar text for a managed dataset card.
 * Shows the current page, total pages, and total record count.
 *
 * @param {string} datasetId - ID of the managed dataset.
 */
function updateManagedPagination(datasetId) {
    const pagination = document.getElementById('md-pagination-' + datasetId);
    const pageInfo   = document.getElementById('md-page-info-'  + datasetId);
    const s = managedState[datasetId];
    if (!s || !pagination) return;
    pagination.classList.add('visible');
    pageInfo.textContent = 'Page ' + s.currentPage + ' of ' + s.totalPages + ' (' + s.allData.length.toLocaleString() + ' total records)';
}

/**
 * @description Delegate an inline Edit button click to the registry's openEdit() callback.
 * The row data is serialised into data-md-row as a JSON string and parsed back here
 * to avoid passing individual column values through the onclick attribute, which
 * would be brittle for rows with many or variable columns.
 *
 * @param {HTMLElement} btn - The clicked Edit button with data-md-id and data-md-row attributes.
 */
function managedEdit(btn) {
    const cfg = MANAGED_DATASETS.find(d => d.id === btn.dataset.mdId);
    if (cfg) cfg.openEdit(JSON.parse(btn.dataset.mdRow));
}

/**
 * @description Delegate an inline Delete button click to the registry's openDelete() callback.
 * Same data-passing pattern as managedEdit().
 *
 * @param {HTMLElement} btn - The clicked Delete button with data-md-id and data-md-row attributes.
 */
function managedDelete(btn) {
    const cfg = MANAGED_DATASETS.find(d => d.id === btn.dataset.mdId);
    if (cfg) cfg.openDelete(JSON.parse(btn.dataset.mdRow));
}

/**
 * @description Re-fetch a managed dataset card's data if it has already been loaded by the user.
 * Called by other modules (e.g. settings.js) after they create, edit, or delete a record
 * so the dataset card stays in sync without requiring a full page reload.
 * No-ops if the card has never been viewed (allData === null) to avoid unnecessary requests.
 *
 * @param {string} datasetId - ID of the managed dataset to refresh (e.g. 'EDbeds').
 */
function refreshManagedCard(datasetId) {
    const s = managedState[datasetId];
    // Only re-fetch if the user has already opened this card at least once
    if (s && s.allData !== null) {
        loadManagedDisplay(datasetId);
    }
}

// ── Regular read-only dataset cards ───────────────────────────────────────────
// Read-only cards use server-side pagination: each navigation request hits
// GET /api/patient-flow/data/{id}?page=N&page_size=50 and returns only the rows
// for that page along with total_pages and total_records metadata.
// This avoids loading potentially very large CSV files into the browser.

/**
 * @description Generate the full HTML string for a read-only dataset card.
 * localOnly datasets (e.g. Wards, DailyPatients) show a "Refresh" button that
 * simply reloads from local storage rather than pulling from the external API,
 * so the Update button (which triggers a remote fetch) is replaced with a View button.
 *
 * @param {Object}  dataset          - Entry from the DATASETS registry.
 * @param {string}  dataset.id       - Unique identifier used to build element IDs.
 * @param {string}  dataset.name     - Human-readable dataset name.
 * @param {string}  dataset.icon     - Emoji icon.
 * @param {boolean} [dataset.localOnly] - If true, skip the remote-update button.
 * @returns {string} HTML string to be inserted into #datasets-grid.
 */
function createDatasetCard(dataset) {
    return `
        <div class="dataset-card" id="card-${dataset.id}">
            <div class="dataset-header">
                <div class="dataset-title">${dataset.icon} ${dataset.name}</div>
                <div class="dataset-info" id="info-${dataset.id}">Click "View" to load data</div>
            </div>
            <div class="dataset-actions">
                <button class="btn btn-primary" onclick="viewDataset('${dataset.id}')">
                    📊 View
                </button>
                ${dataset.localOnly
                    ? `<button class="btn btn-success" onclick="viewDataset('${dataset.id}')">🔄 Refresh</button>`
                    : `<button class="btn btn-success" onclick="updateDataset('${dataset.id}')">🔄 Update</button>`
                }
            </div>
            <div class="table-container" id="table-${dataset.id}">
                <table>
                    <thead id="thead-${dataset.id}"></thead>
                    <tbody id="tbody-${dataset.id}"></tbody>
                </table>
            </div>
            <div class="pagination" id="pagination-${dataset.id}">
                <div class="pagination-controls">
                    <button class="btn btn-primary" onclick="loadPage('${dataset.id}', 1)">⏮ First</button>
                    <button class="btn btn-primary" onclick="loadPage('${dataset.id}', 'prev')">◀ Prev</button>
                    <button class="btn btn-primary" onclick="loadPage('${dataset.id}', 'next')">Next ▶</button>
                    <button class="btn btn-primary" onclick="loadPage('${dataset.id}', 'last')">Last ⏭</button>
                </div>
                <div class="pagination-info" id="page-info-${dataset.id}"></div>
            </div>
        </div>
    `;
}

/**
 * @description Handle the "View" (and "Refresh" for localOnly) button click.
 * Resets state to page 1 and fetches the first page from the server.
 *
 * @param {string} datasetId - ID of the read-only dataset.
 * @returns {Promise<void>}
 */
async function viewDataset(datasetId) {
    state[datasetId] = { currentPage: 1, pageSize: 50 };
    await loadDatasetPage(datasetId, 1);
}

/**
 * @description Resolve symbolic page names to absolute numbers and navigate.
 * Guards against navigating before any state exists (user calls loadPage before viewDataset).
 *
 * @param {string}        datasetId - ID of the read-only dataset.
 * @param {number|string} page      - Absolute page number or 'prev' / 'next' / 'last'.
 * @returns {Promise<void>}
 */
async function loadPage(datasetId, page) {
    const currentState = state[datasetId];
    if (!currentState) return;

    let newPage = currentState.currentPage;
    if (page === 'prev') newPage = Math.max(1, currentState.currentPage - 1);
    else if (page === 'next') newPage = Math.min(currentState.totalPages, currentState.currentPage + 1);
    else if (page === 'last') newPage = currentState.totalPages;
    else newPage = page;

    await loadDatasetPage(datasetId, newPage);
}

/**
 * @description Fetch one server-side page of a read-only dataset and render it.
 * Updates the pagination state from the `pagination` metadata object returned
 * by the backend so the "Page X of Y" display is always accurate.
 *
 * @param {string} datasetId - ID of the read-only dataset.
 * @param {number} page      - 1-based page number to fetch.
 * @returns {Promise<void>}
 */
async function loadDatasetPage(datasetId, page) {
    const tableContainer = document.getElementById(`table-${datasetId}`);
    const tbody = document.getElementById(`tbody-${datasetId}`);
    const infoDiv = document.getElementById(`info-${datasetId}`);

    // Show loading spinner; also make the table container visible so the spinner shows
    tbody.innerHTML = '<tr><td colspan="100"><div class="loading"><div class="spinner"></div>Loading data...</div></td></tr>';
    tableContainer.classList.add('visible');

    try {
        const response = await fetch(`${API_BASE}/data/${datasetId}?page=${page}&page_size=50`);
        const result = await response.json();

        if (!response.ok) {
            throw new Error(result.detail || `HTTP ${response.status}`);
        }

        // Persist pagination metadata returned by the server for use by loadPage()
        state[datasetId] = {
            currentPage: result.pagination.page,
            pageSize: result.pagination.page_size,
            totalPages: result.pagination.total_pages,
            totalRecords: result.pagination.total_records
        };

        displayData(datasetId, result.data);
        updatePagination(datasetId);
        infoDiv.textContent = `${result.pagination.total_records.toLocaleString()} records`;

    } catch (error) {
        tbody.innerHTML = `<tr><td colspan="100" style="color: #dc3545; text-align: center; padding: 20px;">Error: ${error.message}</td></tr>`;
        showMessage(`Error loading ${datasetId}: ${error.message}`, 'error');
    }
}

/**
 * @description Render a page of rows into the read-only dataset card's table.
 * Column headers are derived from the first row's keys so the table automatically
 * adapts to whatever columns the server returns, formatted by formatHeader().
 * Cell values are passed through formatValue() to truncate very long strings.
 *
 * @param {string}        datasetId - ID of the dataset (used to find thead/tbody elements).
 * @param {Array<Object>} data      - Array of row objects from the server response.
 */
function displayData(datasetId, data) {
    const thead = document.getElementById(`thead-${datasetId}`);
    const tbody = document.getElementById(`tbody-${datasetId}`);

    if (!data || data.length === 0) {
        thead.innerHTML = '<tr><th>No Data</th></tr>';
        tbody.innerHTML = `
            <tr>
                <td colspan="100" style="text-align: center; padding: 40px;">
                    <div style="color: #6c757d;">
                        <p style="font-size: 16px; margin-bottom: 10px;">📭 No data available for this dataset</p>
                        <p style="font-size: 14px;">Click the <strong>Update</strong> button to fetch data from the API server</p>
                    </div>
                </td>
            </tr>
        `;
        return;
    }

    // Extract column keys from the first row; all rows are assumed to have the same keys
    const headers = Object.keys(data[0]);
    thead.innerHTML = `<tr>${headers.map(h => `<th>${formatHeader(h)}</th>`).join('')}</tr>`;

    tbody.innerHTML = data.map(row => `
        <tr>
            ${headers.map(h => `<td>${formatValue(row[h])}</td>`).join('')}
        </tr>
    `).join('');
}

/**
 * @description Update the pagination info bar for a read-only dataset card.
 * Makes the pagination control row visible and shows "Page X of Y (Z total records)".
 *
 * @param {string} datasetId - ID of the dataset whose pagination bar to update.
 */
function updatePagination(datasetId) {
    const pagination = document.getElementById(`pagination-${datasetId}`);
    const pageInfo = document.getElementById(`page-info-${datasetId}`);
    const currentState = state[datasetId];

    pagination.classList.add('visible');
    pageInfo.textContent = `Page ${currentState.currentPage} of ${currentState.totalPages} (${currentState.totalRecords.toLocaleString()} total records)`;
}

/**
 * @description Trigger a backend data refresh from the external API server for a
 * read-only dataset, then reload page 1 to show the updated data.
 *
 * POSTs to /api/patient-flow/refresh-data/{id} which instructs the FastAPI backend
 * to pull the latest data from the external data API (port 8100) and overwrite the
 * local CSV file.  Only non-localOnly datasets have this button, so this function
 * will only be called for datasets that have a remote data source.
 *
 * The button is disabled during the request to prevent double-submissions,
 * and its text is restored in the finally block regardless of success or failure.
 *
 * @param {string} datasetId - ID of the read-only dataset to refresh.
 * @returns {Promise<void>}
 */
async function updateDataset(datasetId) {
    // event.target is the button that was clicked (relying on the implicit global `event`)
    const button = event.target;
    const originalText = button.innerHTML;
    button.disabled = true;
    button.innerHTML = '⏳ Updating...';

    showMessage(`Updating ${datasetId} from API server...`, 'info');

    try {
        const response = await fetch(`${API_BASE}/refresh-data/${datasetId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
        });

        const result = await response.json();

        if (!response.ok) {
            throw new Error(result.detail || `HTTP ${response.status}`);
        }

        showMessage(`${datasetId} updated successfully! ${result.records.toLocaleString()} records`, 'success');

        // Reload page 1 only if the user has previously viewed this card;
        // if they haven't opened it yet, there's no table to refresh
        if (state[datasetId]) {
            await loadDatasetPage(datasetId, 1);
        }

    } catch (error) {
        showMessage(`Error updating ${datasetId}: ${error.message}`, 'error');
    } finally {
        // Always restore the button regardless of success or failure
        button.disabled = false;
        button.innerHTML = originalText;
    }
}
